-- Phase 3: public order confirmation links + email locale.
-- `accessToken` is generated by Prisma (`cuid()`), so no database default is
-- needed — the orders table is empty when this runs.
ALTER TABLE "orders" ADD COLUMN     "accessToken" TEXT NOT NULL,
ADD COLUMN     "locale" TEXT NOT NULL DEFAULT 'en';

CREATE UNIQUE INDEX "orders_accessToken_key" ON "orders"("accessToken");
